# Let me look at the simpler transformations to build intuition
inputs = ['vvhjk', 'gkbe', 'uhya', 'zb', 'zgdfdz']
outputs = ['vvhjja', 'gjagyve', 'uhya', 'ggyv', 'gghhzgfhhzgg']

# Look for common character substitutions
replacements = {}

for inp, outp in zip(inputs, outputs):
    min_len = min(len(inp), len(outp))
    for i in range(min_len):
        if inp[i] != outp[i]:
            if inp[i] not in replacements:
                replacements[inp[i]] = outp[i]
            else:
                # If we already have a replacement for this char, 
                # we need to make sure it's consistent
                if replacements[inp[i]] != outp[i]:
                    print(f"Conflict: {inp[i]} maps to both {replacements[inp[i]]} and {outp[i]}")

print("Character mappings found:")
for char, replacement in replacements.items():
    print(f"  '{char}' -> '{replacement}'")

# Also check for additions (length increases)
print("\nLength changes:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    diff = len(outp) - len(inp)
    if diff > 0:
        print(f"'{inp}' -> '{outp}' (added {diff} chars)")
    elif diff < 0:
        print(f"'{inp}' -> '{outp}' (removed {-diff} chars)")
    else:
        print(f"'{inp}' -> '{outp}' (same length)")

